\title{Building codes with transversal CCZ using projective geometry and SAT solvers}
\author{Bohan Lu}
\email{bohan.lu@duke.edu}
\affiliation{Duke Quantum Center, Duke University, Durham, NC 27701, USA}
\affiliation{Department of Electrical and Computer Engineering, Duke University, Durham, NC 27708, USA}
\author{Kenneth R. Brown}
\affiliation{Duke Quantum Center, Duke University, Durham, NC 27701, USA}
\affiliation{Department of Electrical and Computer Engineering, Duke University, Durham, NC 27708, USA}
\affiliation{Department of Physics, Duke University, Durham, NC 27708, USA}
\affiliation{Department of Chemistry, Duke University, Durham, NC 27708, USA}

\begin{abstract}
We construct CSS codes with three logical qubits whose logical CCZ gate is implemented by transversal physical $T/T^{\dagger}$ gates and whose distance is at least $3$. These codes start with $8$-divisible $X$-stabilizers defined by projective geometry, which guarantees $d_Z\geq 3$. A SAT solver then finds three $X$-logical operators compatible with the transversal CCZ. We build codes at thirteen block lengths from $n=48$ to $n=496$, with $d_Z=3$ or $4$, and illustrate the method with the $\nkd{48}{3}{3}$ code $\Qcode$. Additionally, we prove that no CSS code with three logical qubits, $Z$-distance at least $3$, and a quasi-transversal CCZ gate (transversal $T$ with a diagonal Clifford correction) exists below $n=39$. The $\nkd{47}{3}{3}$ code of Jacinto et al.\ serves as an upper bound, leaving $39\le n\le46$ open.
\end{abstract}

\maketitle
\hypersetup{pdftitle={Building codes with transversal CCZ using projective geometry and SAT solvers}}

