\appendix
\section{Shared algebra and coding theory facts}\label{app:exp-facts}

\subsection{Boolean functions and Reed--Muller codes}\label{app:exp-facts-boolean}

This subsection collects the facts about Boolean functions on $\F_2^m$ and
Reed--Muller codes that Appendices~\ref{app:exp-search}--\ref{app:exp-floor} use.

\begin{lemma}[XOR expansion]\label{lem:exp-xorlift}
For bits $a_1,\dots,a_m\in\{0,1\}$,
\begin{equation}\label{eq:exp-xorlift}
a_1\oplus\cdots\oplus a_m
\;=\;\sum_{\emptyset\ne T\subseteq\{1,\dots,m\}}(-2)^{|T|-1}\prod_{i\in T}a_i .
\end{equation}
\end{lemma}
\begin{proof}
Induct on $m$, starting from the two-bit case $a\oplus b=a+b-2ab$, with the induction hypothesis
\begin{equation*}
a_1\oplus\cdots\oplus a_{m-1}
\;=\;\sum_{\emptyset\ne T\subseteq\{1,\dots,m-1\}}(-2)^{|T|-1}\prod_{i\in T}a_i .
\end{equation*}
Let $a=a_m,\ b = a_1\oplus\cdots\oplus a_{m-1}$ and apply the two-bit case.
\end{proof}

\begin{corollary}[XOR and Hamming weight]\label{cor:exp-xorweight}
For bits $a,b\in\{0,1\}$, $2ab=a+b-(a\oplus b)$.
Consequently, if $\xi$ and $\eta$ are binary strings of the same length, $\xi\oplus\eta$
denotes coordinatewise XOR, $\lvert \xi\rvert$ denotes Hamming weight, and $\wedge$
denotes entrywise product, then
\begin{equation}\label{eq:exp-weightxor}
\lvert \xi\oplus\eta\rvert=\lvert \xi\rvert+\lvert \eta\rvert-2\lvert\xi\wedge\eta\rvert.
\end{equation}
For binary strings $\xi,\xi',\eta,\eta'$ of the same length,
\begin{equation*}
\lvert(\xi\oplus\xi')\wedge\eta\wedge\eta'\rvert\equiv
\lvert\xi\wedge\eta\wedge\eta'\rvert+\lvert\xi'\wedge\eta\wedge\eta'\rvert\pmod2.
\end{equation*}
Setting $\eta'=\mathbf1$, the all-ones string, gives the same additivity for
$\lvert\xi\wedge\eta\rvert$, and setting $\eta=\eta'=\mathbf1$ gives it for $\lvert\xi\rvert$.
\end{corollary}
\begin{proof}
Applying $2ab=a+b-(a\oplus b)$
coordinatewise gives~\eqref{eq:exp-weightxor}, and distributivity of $\wedge$ over $\oplus$
gives the overlap-parity claim.
\end{proof}

\begin{lemma}[Coefficient extraction and support parity]\label{lem:exp-coefficient-parity}
Let $\mathbb K$ be $\Z$ or $\F_2$, and let $F\colon\F_2^m\to\mathbb K$ have the multilinear expansion
$F=\sum_{R\subseteq\{1,\ldots,m\}}c_Rm_R$ with $c_R\in\mathbb K$, where
$m_R(v)=\prod_{i\in R}v_i$. If $\mathbf1_{T'}$ is one on $T'$ and zero elsewhere, then
for every $T\subseteq\{1,\ldots,m\}$
\begin{equation}\label{eq:exp-topcoeff}
c_T=\sum_{T'\subseteq T}(-1)^{|T|-|T'|}F(\mathbf1_{T'}).
\end{equation}
In particular, for $\mathbb K=\F_2$ and $T=\{1,\ldots,m\}$, every sign equals $1$ and
$\mathbf1_{T'}$ runs over all of $\F_2^m$, so
\begin{equation}\label{eq:exp-topcoeff-parity}
c_{\{1,\ldots,m\}}=\sum_{v\in\F_2^m}F(v).
\end{equation}
\end{lemma}
\begin{proof}
Substitution of the multilinear expansion into the first sum makes the coefficient of $c_R$
equal to
$\sum_{R\subseteq T'\subseteq T}(-1)^{|T|-|T'|}=(1-1)^{|T|-|R|}$, which is one for $R=T$ and zero
otherwise. The case $\mathbb K=\F_2$ and $T=\{1,\ldots,m\}$
gives~\eqref{eq:exp-topcoeff-parity}.
\end{proof}

\begin{lemma}[Origin indicator]\label{lem:exp-origin-indicator}
\phantomsection\label{fact:exp-origin-degree}
On $\F_2^m$, let $\delta_0(v)=\prod_{i=1}^m(1+v_i)$ be the indicator of the origin.
The indicator has degree $m$, and
\begin{equation}\label{eq:exp-deltainner}
\langle\delta_0,\mathbf 1\rangle=1,
\qquad
\langle\delta_0,m_T\rangle=m_T(0)=0
\quad\text{for every nonempty }T\subseteq\{1,\ldots,m\}.
\end{equation}
\end{lemma}
\begin{proof}
The product defining $\delta_0$ contains the degree-$m$ monomial $v_1\cdots v_m$ and
equals one only at the origin. Hence its inner product with a function $f$ is $f(0)$. Equation~\eqref{eq:exp-deltainner}
follows for $f=1$ and for every nonconstant monomial.
\end{proof}

\begin{lemma}[Affine changes of Boolean functions]\label{lem:exp-affine-invariance}
An \emph{invertible affine map} on $\F_2^m$ is a map
$L\colon\F_2^m\to\F_2^m$ of the form
\begin{equation}\label{eq:exp-affine-map}
L(x)=Ax+b,
\end{equation}
where $A\in\operatorname{GL}(m,2)$ and $b\in\F_2^m$. For a set
$E\subseteq\F_2^m$, write $L(E)=\{L(x):x\in E\}$ for its direct image.
Boolean functions $c,c'\colon\F_2^m\to\F_2$ are \emph{affine-equivalent}
when $c'=c\circ L^{-1}$ for such a map $L$. The induced transformation satisfies
\begin{equation*}
\supp(c')=L(\supp(c)),\qquad |c'|=|c|,\qquad \deg c'=\deg c.
\end{equation*}
\end{lemma}
\begin{proof}
For $y\in\F_2^m$, $c'(y)=1$ if and only if $c(L^{-1}(y))=1$.
Hence $\supp(c')=\{L(x):c(x)=1\}=L(\supp(c))$, and bijectivity gives the weight
identity. Substitution of affine linear forms gives
$\deg(c\circ L^{-1})\le\deg c$, and substituting into $c=c'\circ L$ gives the
opposite inequality.
\end{proof}

\phantomsection\label{app:exp-quadratic-normal-forms}
\paragraph{Quadratic normal forms.}
Dickson's classification~\cite[Ch.~15, Thms.~4--5]{macwilliams1977theory} gives the
following representatives of quadratic Boolean functions under affine equivalence:
\begin{equation}\label{eq:exp-dickson-general}
c(L(y))=\sum_{i=1}^{t}y_{2i-1}y_{2i}+\ell(y)+\varepsilon.
\end{equation}
Here $0\le2t\le m$, $\varepsilon\in\F_2$, and $\ell$ is either zero or
$y_{2t+1}$, with the latter choice available only when $2t<m$. A nonconstant
degree-one function has the form $c(y)=a\cdot y+\varepsilon$, with $a\ne0$, and
\begin{equation}\label{eq:exp-affine-hyperplane-support}
\supp(c)=\{y\in\F_2^m:a\cdot y=1+\varepsilon\}.
\end{equation}
The support in~\eqref{eq:exp-affine-hyperplane-support} is an affine hyperplane. When the
support contains the origin, its projective
support is obtained by deleting the origin.

\paragraph{Reed--Muller duality.}
For binary Reed--Muller codes~\cite[Ch.~13, Thm.~4, p.~375]{macwilliams1977theory},
\begin{equation}\label{eq:exp-rmdual}
\RM(r,m)^\perp=\RM(m-r-1,m),\qquad\RM(r,m)=\{0\}\ \text{for }r<0.
\end{equation}

\paragraph{Minimum weight.}
\phantomsection\label{fact:exp-rm-minweight}
The minimum weight of $\RM(r,m)$ is $2^{m-r}$, and its minimum-weight codewords are
exactly the indicators of the $(m-r)$-dimensional affine
flats~\cite[Cor.~5.3.3]{assmusKeyDesigns1992}.

\subsection{Operations on codes}\label{app:exp-facts-generators}

Row operations may preserve both code spaces, whereas puncturing can change their dimensions
and distance. The results below specify the effects of these operations on the code parameters
and the CH conditions.

In Appendices~\ref{app:exp-search}--\ref{app:exp-floor}, we write a generator matrix as
$G=[K;S]\in\F_2^{(3+\widetilde s)\times n}$, with logical rows $K_1,K_2,K_3$ and stabilizer rows
$S_1,\ldots,S_{\widetilde s}$. The rows of $G$ span the code $\mathcal C_1$, and the rows of $S$
span the code $\mathcal C_2\subseteq\mathcal C_1$, as for a generator
matrix~\cite[{\S}1.2]{huffmanFundamentals2003}, except that the rows need not be independent.
The code parameters are
\begin{equation*}
s=\dim\mathcal C_2\le\widetilde s,\qquad
k=\dim\mathcal C_1-\dim\mathcal C_2.
\end{equation*}
By~\eqref{eq:exp-dZ}, the $Z$-distance $d_Z$ is the least
weight of a vector in $\mathcal C_2^\perp\setminus\mathcal C_1^\perp$. The parameters $s$, $k$,
and $d_Z$ therefore depend only on the codes $\mathcal C_2\subseteq\mathcal C_1$, and not on the
rows chosen to span them.

Column $j$ of $G$ is a full column
$(\alpha,\beta)$ as in Section~\ref{sec:exp-fg48}, with logical label $\alpha\in\F_2^3$ and
syndrome $\beta\in\F_2^{\widetilde s}$. When $\mathcal C_2$ is projective, the label map $\kappa$
of Section~\ref{sec:exp-full-g} writes each full column as $(\kappa(\beta),\beta)$ with
$\beta\in\mathcal P$, and the logical row $K_i$ is the vector
$(\kappa_i(\beta))_{\beta\in\mathcal P}$. Appendix~\ref{app:exp-search} writes this vector as
$\kappa_i$.

Appendix~\ref{app:exp-floor} works at stabilizer rank $s$, meaning that $S$ has $s$
independent rows, so that the syndromes lie in $\F_2^s$. By
Lemma~\ref{lem:exp-generator-operations}(a) and~(b) below, replacing $S$ by a row basis changes
neither the nine CH conditions nor $n$, $s$, $k$, and $d_Z$.

\begin{corollary}\label{cor:exp-ch-codes}
Let $G=[K;S]$ be the generator matrix for the codes $\mathcal C_2\subseteq\mathcal C_1$. Then $G$ satisfies the nine
CH conditions if and only if
\begin{enumerate}
\item[(i)] $|a\wedge b|$ is even for all $a,b\in\mathcal C_1$,
\item[(ii)] $|a\wedge b\wedge u|$ is even for all $a,b\in\mathcal C_1$ and
$u\in\mathcal C_2$, and
\item[(iii)] $|K_1\wedge K_2\wedge K_3|$ is odd.
\end{enumerate}
In that case every codeword of $\mathcal C_1$ has even weight, by~(i) with $a=b$, and
the following hold.
\begin{enumerate}
\item[(a)] For $x\in\F_2^3$, $y\in\F_2^{\widetilde s}$, and
$\{i,i',i''\}=\{1,2,3\}$,
\begin{equation*}
w=\sum_{h=1}^{3}x_hK_h+\sum_{l=1}^{\widetilde s}y_lS_l
\quad\Longrightarrow\quad
|w\wedge K_{i'}\wedge K_{i''}|\equiv x_i\pmod2.
\end{equation*}
\item[(b)] If $n$ is even, then the matrix $[K;S;\mathbf1^{\mathsf T}]$, with the
all-ones row appended as a stabilizer row, satisfies the nine CH conditions.
\end{enumerate}
\end{corollary}
\begin{proof}
By Corollary~\ref{cor:exp-xorweight}, the parities of $|a\wedge b|$ and $|a\wedge b\wedge u|$ are additive in each argument, so (i)
and~(ii) hold for all codewords exactly when they hold for rows. On rows, $R\wedge R=R$ reduces a
repeated row, (i) becomes K1, K2, KS1, S1, and S2, (ii) becomes KS2, KS3, and S3, and (iii) is
K3.

For part~(a), additivity expresses $|w\wedge K_{i'}\wedge K_{i''}|$ as
$\sum_hx_h|K_h\wedge K_{i'}\wedge K_{i''}|$ plus the overlap of
$\sum_ly_lS_l\in\mathcal C_2$ with $K_{i'}\wedge K_{i''}$. The terms with $h=i',i''$ are even
by~(i), the stabilizer term is even by~(ii), and~(iii) makes the term with $h=i$ equal to $x_i$
mod $2$.

For part~(b), the codes become $\mathcal C_1\cup(\mathbf1+\mathcal C_1)$ and
$\mathcal C_2\cup(\mathbf1+\mathcal C_2)$, and additivity leaves only overlaps containing
$\mathbf1$. Each equals $n$ or an overlap $|a\wedge b|$ with $a,b\in\mathcal C_1$, which is even
by hypothesis or by~(i). Condition~(iii) is unchanged.
\end{proof}

\begin{definition}[Puncturing]\label{def:exp-puncturing}
Let $\mathcal C\subseteq\F_2^n$ be a linear code, and let
$J\subseteq\{1,\ldots,n\}$ be a set of coordinate indices. The \emph{puncture} of
$\mathcal C$ on $J$ is the linear code $\mathcal C'\subseteq\F_2^{n-\lvert J\rvert}$ obtained by
deleting the coordinates in $J$ from every codeword of $\mathcal C$
~\cite[{\S}1.5.1 and Thm.~1.5.1]{huffmanFundamentals2003}.
\end{definition}

\begin{lemma}[Row operations and puncturing]\label{lem:exp-generator-operations}
\begin{enumerate}
\item[(a)] \emph{Left multiplication.} For a matrix $Q$ with $3+\widetilde s$ columns,
\begin{equation*}
\begin{aligned}
\operatorname{rowspan}QG&\subseteq\operatorname{rowspan}G,\\
\operatorname{rank}QG&=\operatorname{rank}Q
&&\text{if the rows of $G$ are independent.}
\end{aligned}
\end{equation*}
The row-space inclusion is an equality when $Q$ is invertible. Adding
one row to another, deleting a row, and replacing $S$ by $AS$ for an invertible
$\widetilde s\times\widetilde s$ matrix $A$ are left multiplications.

Suppose that $G$ satisfies
the nine CH conditions, and let $G'=[K';S']$ have logical rows $K_i'\in K_i+\mathcal C_2$ and
stabilizer rows in $\mathcal C_2$. Then $G'$ satisfies the nine CH conditions. If moreover the
rows of $S'$ span $\mathcal C_2$, then $G'$ and $G$ generate the same codes, and hence the same $n$,
$s$, $k$, and $d_Z$.
\item[(b)] \emph{Row basis.} Let the rows of $S$ indexed by an ordered set $I$ form a
basis of $\mathcal C_2$, and let $S_I$ be the $s\times n$ matrix they form. Restricting a syndrome
$\beta$ to its entries in $I$ gives the corresponding column $\beta_I\in\F_2^s$ of $S_I$.
The restriction preserves distinct and nonzero syndromes, and the columns $\beta_I$
span $\F_2^s$. Thus $S_I$ has the same actual rank as $S$ and is projective with $n$ columns
whenever $S$ is projective.
\item[(c)] \emph{Puncturing.} Let $\mathcal C'$ be the code obtained by puncturing the
set of coordinates $J$ from a code $\mathcal C\subseteq\F_2^n$. Deleting the columns indexed by
$J$ from a matrix whose rows span $\mathcal C$ gives a matrix whose rows span $\mathcal C'$, and
\begin{equation}\label{eq:exp-puncture-rank}
\dim\mathcal C-\dim\mathcal C'
=\dim\{\,c\in\mathcal C:\supp(c)\subseteq J\,\}
\le \lvert J\rvert.
\end{equation}
Write $\iota_J\colon\F_2^{n-|J|}\to\F_2^n$ for insertion of zeros
at each coordinate in $J$. Then $\iota_J(\mathcal C'^\perp)\subseteq\mathcal C^\perp$ and
$|\iota_Jv'|=|v'|$. Consequently, a generator matrix punctured on $J$ has $Z$-distance at least
$d_Z$ of the original.

Moreover, if $\sigma\in\F_2^n$ equals $e_j$ or $e_j+e_{j'}$ with $j\ne j'$
and $G\sigma=0$, then $G$ punctured on $\supp(\sigma)$ satisfies the nine CH conditions exactly
when $G$ does.
\end{enumerate}
\end{lemma}

\begin{proof}
For part~(a), row $i$ of $QG$ is $\sum_jQ_{ij}g^{\,j}$, where $g^{\,j}$ are the
rows of $G$, so $\operatorname{rowspan}QG\subseteq\operatorname{rowspan}G$, and $G=Q^{-1}(QG)$ gives equality when $Q$ is invertible. If the rows of $G$ are
independent, then the columns of $G$ span $\F_2^{3+\widetilde s}$, so the columns of $QG$ span the
column space of $Q$.

For CH preservation, the codes of $G'$ satisfy $\mathcal C_2'\subseteq\mathcal C_2$ and
$\mathcal C_1'\subseteq\mathcal C_1$, so conditions (i) and~(ii) of
Corollary~\ref{cor:exp-ch-codes} for $G'$ are instances of the same conditions for $G$. Writing
$K_i'=K_i+u_i$ with $u_i\in\mathcal C_2$, additivity writes $|K_1'\wedge K_2'\wedge K_3'|$ as
$|K_1\wedge K_2\wedge K_3|$ plus overlaps with a factor $u_i$ and two factors in $\mathcal C_1$,
which are even by~(ii). When the rows of $S'$ span $\mathcal C_2$, the codes of $G'$ equal
$\mathcal C_2\subseteq\mathcal C_1$.

For part~(b), every omitted row is a linear combination of the selected rows,
so $\beta_I$ determines every entry of $\beta$. If $\beta_I=0$, every entry of $\beta$ is zero as well. Finally,
$\operatorname{rowspan}S_I=\mathcal C_2$ gives $\operatorname{rank}S_I=s$, so its columns span
$\F_2^s$.

For part~(c), coordinate deletion is a linear map from $\mathcal C$ onto
$\mathcal C'$ whose kernel consists of the codewords supported inside $J$, and rank--nullity
gives~\eqref{eq:exp-puncture-rank}.

For $v'\in\mathcal C'^\perp$ and $c\in\mathcal C$, let $c'\in\mathcal C'$ be the punctured codeword of
$c$ on $J$, the word obtained by deleting the coordinates in $J$ from $c$. Then the coordinates in $J$ contribute nothing to $c\cdot\iota_Jv'$, so
$c\cdot\iota_Jv'=c'\cdot v'=0$. For the
distance, let $v'$ satisfy $S'v'=0$ and $K'v'\ne0$ for the punctured generator matrix $[K';S']$,
and set $v=\iota_Jv'$. Then $Sv=0$, $Kv=K'v'\ne0$, and $|v|=|v'|$, so~\eqref{eq:exp-dZ} gives
the bound.

Finally, $G\sigma=0$ says that column $j$ is zero or that columns $j$ and $j'$ are
equal. The deleted columns therefore contribute $0$, or the same bit twice, to every overlap of
rows, so every CH parity is the same with and without them.
\end{proof}

\section{SAT search and exclusion}\label{app:exp-search}
Fix a support $\mathcal P$ satisfying S1--S3.
Order the $n$ columns of $\mathcal P$ as they appear in $S$. Each logical row is the vector
\begin{equation*}
\kappa_i=\bigl(\kappa_i(\beta)\bigr)_{\beta\in\mathcal P}
\in\F_2^{\mathcal P}\cong\F_2^n,
\qquad i\in\{1,2,3\}.
\end{equation*}
As in~\eqref{eq:exp-bridge}, all inner products below are over $\mathcal P$, as indicated by the
subscript. For each logical label $\kappa_i$, K1, KS1, and KS3 give, respectively,
\begin{equation}\label{eq:exp-single-label-tests}
\langle\kappa_i,\mathbf1\rangle_{\mathcal P}=0,\qquad
\langle\kappa_i,m_{\{l\}}\rangle_{\mathcal P}=0,\qquad
\langle\kappa_i,m_{\{l,l'\}}\rangle_{\mathcal P}=0.
\end{equation}
The indices are $i\in\{1,2,3\}$,
$1\le l\le s$, and $1\le l<l'\le s$ in the last constraint.
Here $m_{\{l,l'\}}(\beta)=\beta_l\beta_{l'}$ is the product of coordinates $l$ and $l'$ of the
column $\beta\in\mathcal P$. The functions $\mathbf1$, $m_{\{l\}}$, and
$m_{\{l,l'\}}$ span $\RM(2,s)$.
Their restrictions
to $\mathcal P$ therefore span $\operatorname{ev}_{\mathcal P}(\RM(2,s))$, where
$\operatorname{ev}_{\mathcal P}(p)=(p(\beta))_{\beta\in\mathcal P}$ is the evaluation map of
Proposition~\ref{prop:exp-q48-tpattern}.
Consequently, for each $i\in\{1,2,3\}$,
\begin{equation}\label{eq:exp-VA}
\kappa_i\text{ satisfies K1, KS1, and KS3}
\quad\Longleftrightarrow\quad
\kappa_i\in V_{\mathcal P}:=
\bigl(\operatorname{ev}_{\mathcal P}(\RM(2,s))\bigr)^{\perp}
\subseteq\F_2^n.
\end{equation}
Call $(\kappa_1,\kappa_2,\kappa_3)$ a \emph{CH triple} when the three logical rows
satisfy all CH conditions on $\mathcal P$.
Equation~\eqref{eq:exp-VA}
places both in $V_{\mathcal P}$, and K2 and KS2 impose
\begin{equation}\label{eq:exp-admissible-pair}
\langle\kappa_1\kappa_2,\mathbf1\rangle_{\mathcal P}=0,\qquad
\langle\kappa_1\kappa_2,m_{\{l\}}\rangle_{\mathcal P}=0.
\end{equation}
The second constraint in~\eqref{eq:exp-admissible-pair} ranges over $1\le l\le s$.
The first two labels of every CH triple therefore form an ordered pair
$(\kappa_1,\kappa_2)\in(V_{\mathcal P}\setminus\{0\})\times(V_{\mathcal P}\setminus\{0\})$ satisfying
these equations, so enumerating all such pairs covers every possible CH triple. For a fixed pair,
the remaining conditions on $\kappa_3\in V_{\mathcal P}$ are
\begin{equation}\label{eq:exp-floor-third-label}
\begin{aligned}
\langle\kappa_3,\kappa_i\rangle_{\mathcal P}&=0 &&\text{(K2)},\\
\langle\kappa_3,m_{\{l\}}\kappa_i\rangle_{\mathcal P}&=0 &&\text{(KS2)},\\
\langle\kappa_3,\kappa_1\kappa_2\rangle_{\mathcal P}&=1 &&\text{(K3)}.
\end{aligned}
\end{equation}
The indices satisfy $i\in\{1,2\}$ and $1\le l\le s$.
Membership in $V_{\mathcal P}$ imposes K1, KS1, and KS3 on $\kappa_3$,
while~\eqref{eq:exp-floor-third-label} imposes K2, KS2, and K3.
Let $d=\dim V_{\mathcal P}=n-\dim\operatorname{ev}_{\mathcal P}(\RM(2,s))$, let
$v_1,\ldots,v_d$ be a basis of $V_{\mathcal P}$, and write the vector
$\kappa_3=\sum_{a=1}^dt_av_a$ with $t_a\in\F_2$. By
Corollary~\ref{cor:exp-xorweight}, substitution into
\eqref{eq:exp-floor-third-label} gives the binary linear system
\begin{equation}\label{eq:exp-third-label-coefficients}
\begin{aligned}
\sum_{a=1}^d t_a\langle v_a,\kappa_i\rangle_{\mathcal P}&=0,
&&i\in\{1,2\},\\
\sum_{a=1}^d t_a\langle v_a,m_{\{l\}}\kappa_i\rangle_{\mathcal P}&=0,
&&i\in\{1,2\},\ 1\le l\le s,\\
\sum_{a=1}^d t_a\langle v_a,\kappa_1\kappa_2\rangle_{\mathcal P}&=1.&
\end{aligned}
\end{equation}
Since $\kappa_1$, $\kappa_2$, and the basis vectors $v_a$ are fixed, every inner product
in~\eqref{eq:exp-third-label-coefficients} is a known bit, so~\eqref{eq:exp-third-label-coefficients}
is a linear system over $\F_2$ in $t_1,\ldots,t_d$. Gaussian elimination then decides whether the pair extends to a CH triple.
Failure to extend to a CH triple for every possible pair $\kappa_1,\kappa_2$ excludes $\mathcal P$.
When Equation~\eqref{eq:exp-third-label-coefficients} admits a solution, its solutions form an affine space, a particular solution
plus the kernel of the coefficient matrix, and each solution gives a label $\kappa_3$ that extends
the pair to a CH triple. Deciding whether $\mathcal P$ carries a CH triple needs only one solution.

\begin{algorithm}[htbp]
\caption{Finding CH label maps by SAT or testing all label maps on a specified support, followed by binary flip-vector feasibility ($k=3$, $d_Z\ge3$)}\label{alg:exp-search}
\begin{algorithmic}[1]
\Statex \textit{Find a code by SAT:}
\State For each of the $2^s-1$ nonzero $\beta$ introduce the support bit $\chi_S(\beta)$ and the
three label bits $\kappa_i(\beta)$, $i\in\{1,2,3\}$, for $4(2^s-1)$ support and logical label variables,
before encoding auxiliaries
\State For each nonzero $\beta$ and each nonempty $T_K\subseteq\{1,2,3\}$, introduce an
auxiliary variable with clauses that force it to equal
$\chi_S(\beta)\prod_{i\in T_K}\kappa_i(\beta)$. Impose K1--K3, KS1--KS3, and S1--S3 as the XOR
equations~\eqref{eq:exp-clause}, whose terms are support bits and these auxiliary variables.
Conditions S1--S3 restrict the support to
$\RM(s-4,s)\cup\bigl(\delta_0+\RM(s-4,s)\bigr)$, where $\delta_0$ is the origin indicator
\State Solve the constraints globally with a SAT solver. Each satisfying assignment
supplies $\chi_S$ and $\kappa$, and hence a generator matrix such as $\Qcode$
\Statex \textit{Alternatively, test a candidate support $\mathcal P$}:
\State For a support $\mathcal P$ satisfying S1--S3, enumerate every
ordered pair of nonzero $\kappa_1,\kappa_2\in V_{\mathcal P}$
satisfying~\eqref{eq:exp-admissible-pair}. Solve the
system~\eqref{eq:exp-third-label-coefficients} by Gaussian elimination. Each solution
$t_1,\ldots,t_d$ gives a label $\kappa_3\in V_{\mathcal P}$ and a generator matrix. Failure to
extend to a CH triple for every possible pair $\kappa_1,\kappa_2$ excludes $\mathcal P$. Exhausting all supports
satisfying S1--S3 proves non-existence
\Statex \textit{For either route, test the physical signs:}
\State For each generator matrix obtained from SAT or a consistent
fixed-support system, solve~\eqref{eq:exp-Z4half} for a binary $\gamma$.
A solution gives a $T/T^\dagger$ implementation of Definition~\ref{def:exp-CI}
\end{algorithmic}
\end{algorithm}
