\subsection{Stabilizer-rank reduction and hyperplane supports}\label{app:exp-rank-reductions}

Let $G=[K;S]$ satisfy the nine CH conditions with $k=3$ and $d_Z\ge3$ and $\mathcal C_2$ projective. Express $G$ in
terms of its set $\mathcal P$ of syndrome columns:
\begin{equation}\label{eq:exp-rank-reduction-columns}
G=\left(\binom{\kappa(\beta)}{\beta}\right)_{\beta\in\mathcal P}.
\end{equation}

To delete one independent stabilizer row, construct a projection
$\pi:\F_2^s\to\F_2^{s-1}$ with a one-dimensional kernel,
generated by a nonzero vector $v\in\F_2^s$:
\begin{equation}\label{eq:exp-levelred-kernel}
\ker\pi=\langle v\rangle=\{0,v\}.
\end{equation}
Choose $m$ with $v_m=1$, and define $\pi$ by
\begin{equation*}
\pi(\beta)=\bigl(\beta_l+v_l\beta_m\bigr)_{l\ne m}.
\end{equation*}
If $\pi(\beta)=0$, then $\beta_l=v_l\beta_m$ for $l\ne m$, hence
$\beta=\beta_mv$. For $\delta\in\F_2^3$, apply the row operations
\begin{equation*}
K_i\mapsto K_i+\delta_iS_m\quad(1\le i\le3),\qquad
S_l\mapsto S_l+v_lS_m\quad(l\ne m),
\end{equation*}
and delete $S_m$. The full-column operation is
\begin{equation}\label{eq:exp-levelred-full-map}
\binom{\alpha}{\beta}\longmapsto
\binom{\alpha+\beta_m\delta}{\pi(\beta)},\qquad
\alpha\in\F_2^3,\quad\beta\in\F_2^s.
\end{equation}
Equation~\eqref{eq:exp-levelred-kernel} and $v_m=1$ give
\begin{equation}\label{eq:exp-levelred-full-kernel}
\binom{\alpha+\beta_m\delta}{\pi(\beta)}=0
\quad\Longleftrightarrow\quad
\binom{\alpha}{\beta}\in\left\{0,\binom{\delta}{v}\right\}.
\end{equation}

Whether the output keeps $d_Z\ge3$ depends on the labels of the syndromes that differ
by $v$. For nonzero $v\in\F_2^s$, collect their label differences:
\begin{equation}\label{eq:exp-labeldiff}
\Delta_v=\bigl\{\,\kappa(\beta+v)+\kappa(\beta)
 : \{\beta,\beta+v\}\subseteq\mathcal P\,\bigr\}\subseteq\F_2^3.
\end{equation}
Several pairs may give the same value, and $\Delta_v=\emptyset$ when no supported pair
differs by $v$.

\begin{lemma}\label{lem:exp-projection}
Let $G=[K;S]$ satisfy the nine CH conditions with $k=3$, $d_Z\ge3$, and
$\mathcal C_2$ projective, at stabilizer rank $s$. Let $\pi$, $v$, $m$, and $\delta$ be as above,
and suppose that
\begin{enumerate}
\item[(i)] $\Delta_v\subseteq\{\delta\}$, and
\item[(ii)] $\kappa(v)=\delta$ if $v\in\mathcal P$.
\end{enumerate}
Let
\begin{equation*}
G'=[K';S']=
\left(\binom{\kappa(\beta)+\beta_m\delta}{\pi(\beta)}\right)_{\beta\in\mathcal P}.
\end{equation*}
Then $G'$ satisfies the nine CH conditions with $k'=3$, $d_Z'\ge3$, and
$\operatorname{rank}S'=s-1$. A column of $G'$ is zero, or two distinct columns of $G'$ are
equal, in the following cases:
\begin{align}
\binom{\kappa(\beta)+\beta_m\delta}{\pi(\beta)}=0
&\quad\Longleftrightarrow\quad\beta=v,\label{eq:exp-projection-zero}\\
\binom{\kappa(\beta)+\beta_m\delta}{\pi(\beta)}=
\binom{\kappa(\beta')+\beta'_m\delta}{\pi(\beta')}
&\quad\Longleftrightarrow\quad\beta'=\beta+v,\label{eq:exp-projection-equal}
\end{align}
where $\beta,\beta'\in\mathcal P$ and $\beta\ne\beta'$ in the second line.
Applying Lemma~\ref{lem:exp-projred} to $G'$ gives a generator matrix of stabilizer rank at most
$s-1$ and length at most $n$ with $k=3$, all nine CH conditions, $d_Z\ge3$, and
$\mathcal C_2$ projective.
\end{lemma}

\begin{proof}
Each new logical row is $K_i+\delta_iS_m$, and each retained stabilizer row is
$S_l+v_lS_m$. Lemma~\ref{lem:exp-generator-operations}(a) therefore gives the CH conditions
for $G'$.

Since $k=3$ and the $s$ rows of $S$ are independent, the $s+3$ rows of $G$ are
independent. The row additions preceding~\eqref{eq:exp-levelred-full-map} are invertible.
Deleting $S_m$ therefore leaves $s+2$ independent rows of $G'$ and $s-1$ independent
stabilizer rows, so
\begin{equation*}
\operatorname{rank}G'=s+2,\qquad
\operatorname{rank}S'=s-1,\qquad k'=(s+2)-(s-1)=3.
\end{equation*}

For distinct $\beta,\beta'\in\mathcal P$, Equation~\eqref{eq:exp-levelred-kernel}
gives $\pi(\beta)=\pi(\beta')$ exactly when $\beta'=\beta+v$. Condition~(i) then gives
$\kappa(\beta')+\kappa(\beta)=\delta$. The two input columns differ by $(\delta,v)$, so their
images under~\eqref{eq:exp-levelred-full-map} agree by~\eqref{eq:exp-levelred-full-kernel}.
Conversely, equal columns have equal syndromes, so $\beta'=\beta+v$, and
\eqref{eq:exp-projection-equal} follows.

The syndrome $\pi(\beta)$ of a column of $G'$ is zero exactly when
$\beta\in\ker\pi=\{0,v\}$. Since $0\notin\mathcal P$, this happens exactly when $\beta=v$ and
$v\in\mathcal P$. In that case condition~(ii) gives $\kappa(v)=\delta$, and $v_m=1$ makes the new
label $\kappa(v)+v_m\delta=0$, so the column is zero by~\eqref{eq:exp-levelred-full-kernel}.
Conversely, a zero column has zero syndrome, so $\beta=v$, and
\eqref{eq:exp-projection-zero} follows.
By~\eqref{eq:exp-projection-equal}, two columns of $G'$ with the same nonzero syndrome
are equal, so they carry the same logical label. By~\eqref{eq:exp-projection-zero}, a column of
$G'$ with zero syndrome has logical label zero. Lemma~\ref{lem:exp-fiber}(b) requires exactly
these two properties, so $d_Z'\ge3$.

Lemma~\ref{lem:exp-projred} removes zero columns and pairs of equal columns
while retaining CH, $k'=3$, and $d_Z'\ge3$.
\end{proof}

The hypotheses of Lemma~\ref{lem:exp-projection} follow from counting in
Appendix~\ref{app:exp-levelred-proof}, or from hyperplane containment in
Appendix~\ref{app:exp-hyperplane-reductions}, which we discuss below.

\subsubsection{General rank reduction}\label{app:exp-levelred-proof}

\begin{proof}[Proof of Lemma~\ref{lem:exp-levelred}]

Each unordered pair of distinct columns $\{\beta,\beta+v\}\subseteq\mathcal P$ determines the
unique nonzero difference $v$. A vector $v$ with $\lvert\Delta_v\rvert\ge2$ accounts for at
least two pairs, and no pair is counted for two different $v$. Hence
\begin{equation}\label{eq:exp-levelred-count}
\#\{\,v:\lvert\Delta_v\rvert\ge2\,\}
\le \Bigl\lfloor\tbinom n2\big/2\Bigr\rfloor.
\end{equation}
Exactly $n$ vectors $v$ lie in $\mathcal P$.
There are $2^s-1$ nonzero vectors $v$, so
\begin{equation*}
\#\{\,v:v\notin\mathcal P\ \text{and}\ \lvert\Delta_v\rvert\le1\,\}
\ge 2^s-1-n-\Bigl\lfloor\tbinom n2\big/2\Bigr\rfloor.
\end{equation*}

\phantomsection\label{proof:exp-levelred-construction}
The hypothesis of Lemma~\ref{lem:exp-levelred} makes this lower bound positive.
Fix a nonzero
$v\notin\mathcal P$ with $\lvert\Delta_v\rvert\le1$. Let $\delta$ be the unique element of
$\Delta_v$ when the set is nonempty, and set $\delta=0$ otherwise.
Both hypotheses of Lemma~\ref{lem:exp-projection} hold: $\Delta_v\subseteq\{\delta\}$
and $v\notin\mathcal P$. Applying the lemma proves the claimed reduction.

\end{proof}

