\section{Inclusive Error Model}
\label{app:inc_err}

In our simulations, we parametrized $\vb p$ by error types $t(e)$ for error mechanism $e$, as shown in Table~\ref{tab:fault_type_channel_class}.
Each error $e$ is sampled according to an inclusive error model \cite{chaoOptimizationSurfaceCode2020}:
\begin{equation}
    W_e(\pvec) = 
    \begin{cases}
        p_{t(e)}
        & \text{if } n_{c(e)} = 1, \\
        \dfrac12
        -
        \dfrac12
        \left(
            1-
            \dfrac{2^{n_{c(e)}}}{2^{n_{c(e)}}-1}
            p_{t(e)}
        \right)^{2^{1 - n_{c(e)}}}
        & \text{if } n_{c(e)} \geq 2.
    \end{cases},
    \label{eq:edge_weight}
\end{equation}

Each error mechanism is also assigned an error channel class $c(e)$, with a corresponding integer value for $n_{c(e)}$ (Table~\ref{tab:fault_type_channel_class}). $2^{n_{c(e)}}-1$ is the number of independent mechanisms associated with a channel $c(e)$, and $p_{t(e)}$ is the physical error rate assigned to $t(e)$.

\begin{table}
\centering
\caption{Error types $t(e)$, their channel classes $c(e)$, and the corresponding values of $n_{c(e)}$.}
\label{tab:fault_type_channel_class}
\begin{tabular}{lll}
\toprule
Channel class $c(e)$ & Example error types $t(e)$ & $n_{c(e)}$ \\
\midrule
Single-qubit bit-flip     & Measurement, initialization       & 1 \\
Single-qubit depolarizing & Single-qubit gate, idle           & 2 \\
Two-qubit depolarizing    & Two-qubit gate                    & 4 \\
\bottomrule
\end{tabular}
\end{table}

Hence,
\begin{equation}
    \pdv{W_e(\pvec)}{p_i}
    =
    \mathds{1}[t(e)=i]
    \begin{cases}
        1
        & \text{if } c(e) = \text{single-qb bitflip}, \\
        \dfrac13
        \left(1 - \dfrac{4p_i}{3} \right)^{-1/2}
        & \text{if } c(e) = \text{single-qb depolarizing}, \\
        \dfrac{1}{15}
        \left(1 - \dfrac{16p_i}{15} \right)^{-7/8}
        & \text{if } c(e) = \text{two-qb depolarizing}.
    \end{cases}
    \label{eq:fault_prob_derivative}
\end{equation}

\section{Variance Ratio}
\label{app:uncertainty}

For the differentiable estimator,
\begin{equation}
    \hat{\nu}_i^{\mathrm{Diff}}
    =
    \frac{1}{N}\sum_{k=1}^{N}S_{i,k},
    \qquad
    S_{i,k}
    =
    L(E_k)\pdv{p_i}\log \pr_{\pvec}(E_k)
    \equiv
    L(E_k)A_i(E_k).
\end{equation}
Using Eq.~\ref{eq:sens_model},
\begin{equation}
    A_i(E)
    =
    \sum_{e\in E}
    \pdv{W_e}{p_i}\frac{1}{W_e}
    -
    \sum_{e\notin E}
    \pdv{W_e}{p_i}\frac{1}{1-W_e}.
    \label{eq:appendix-score}
\end{equation}
Assuming independent shots,
\begin{equation}
    \mathrm{Var}\!\left(\hat{\nu}_i^{\mathrm{Diff}}\right)
    =
    \frac{\mathrm{Var}(S_i)}{N}.
    \label{eq:diff-var}
\end{equation}
For small \(p_L\),
\begin{align}
    \mathrm{Var}(S_i)
    &=
    \mathbb E[S_i^2]-\mathbb E[S_i]^2 \\
    &\approx
    \mathbb E[S_i^2] \\
    &=
    p_L\,\mathbb E[A_i^2\mid L].
    \label{eq:score-var-low-pl}
\end{align}

For small physical error rates, the DEM probabilities associated with channel \(i\) are linear to leading order,
\begin{equation}
    W_e(p_i)\approx \alpha_e p_i,
    \qquad
    \pdv{W_e}{p_i}\approx\alpha_e.
\end{equation}
Rearranging Eq.~\eqref{eq:appendix-score},
\begin{align}
    A_i(E)
    &=
    \sum_{e\in E}
    \pdv{W_e}{p_i}
    \left(\frac{1}{W_e}+\frac{1}{1-W_e}\right)
    -
    \sum_e
    \pdv{W_e}{p_i}\frac{1}{1-W_e} \\
    &=
    \frac{M_i(E)}{p_i}+O(1),
    \label{eq:Mi-scaling}
\end{align}
where \(M_i(E)\) is the effective number of channel-\(i\) faults in the sampled fault configuration. Hence
\begin{equation}
    \mathbb E[A_i^2\mid L]
    =
    \frac{\mathbb E[M_i^2\mid L]}{p_i^2}
    +O\!\left(\frac{1}{p_i}\right),
\end{equation}
and therefore
\begin{equation}
    \mathrm{Var}\!\left(\hat{\nu}_i^{\mathrm{Diff}}\right)
    \approx
    \frac{p_L}{Np_i^2}
    \mathbb E[M_i^2\mid L].
    \label{eq:diff-var-scaling}
\end{equation}

For central finite differences,
\begin{equation}
    \hat{\nu}_i^{\mathrm{FD}}
    =
    \frac{\hat p_L^+-\hat p_L^-}{2h},
    \qquad
    \hat p_L^{\pm}
    =
    \frac{1}{n_{\pm}}\sum_{k=1}^{n_{\pm}}L(E_k^{\pm}).
\end{equation}
Since \(\hat p_L^{\pm}\) are Bernoulli sample means,
\begin{equation}
    \mathrm{Var}(\hat p_L^{\pm})
    =
    \frac{p_L^{\pm}(1-p_L^{\pm})}{n_{\pm}}
    \approx
    \frac{p_L^{\pm}}{n_{\pm}},
\end{equation}
so
\begin{equation}
    \mathrm{Var}\!\left(\hat{\nu}_i^{\mathrm{FD}}\right)
    \approx
    \frac{p_L^+/n_+ + p_L^-/n_-}{4h^2}.
    \label{eq:fd-var}
\end{equation}

Let \(s\) be the number of error types. For equal total shot budget \(N\), finite differences use
\begin{equation}
    n_+=n_-=\frac{N}{2s}.
\end{equation}
Using \(p_L^++p_L^-\approx2p_L\),
\begin{equation}
    \mathrm{Var}\!\left(\hat{\nu}_i^{\mathrm{FD}}\right)
    \approx
    \frac{s p_L}{Nh^2}.
    \label{eq:fd-var-scaling}
\end{equation}
The variance ratio is therefore
\begin{align}
    R_i
    &\equiv
    \frac{\mathrm{Var}(\hat{\nu}_i^{\mathrm{FD}})}
    {\mathrm{Var}(\hat{\nu}_i^{\mathrm{Diff}})} \\
    &\approx
    \frac{s p_i^2}
    {h^2\,\mathbb E[M_i^2\mid L]}.
    \label{eq:ratio-general}
\end{align}
$ \expec[M_i^2\mid L]$ is the expected squared number of channel-$i$ faults involved in logical failures.

For a relative finite-difference step \(h=a p_i\),
\begin{equation}
    R_i
    \approx
    \frac{s}{a^2\,\mathbb E[M_i^2\mid L]}.
    \label{eq:ratio-relative-step}
\end{equation}
In our simulations, \(s=5\) and \(a=0.1\), giving
\begin{equation}
    R_i
    \approx
    \frac{500}{\mathbb E[M_i^2\mid L]}.
    \label{eq:ratio_exp}
\end{equation}

We used Eq.~\ref{eq:ratio_exp} to predict the value of $\mathrm{Var}(\hat \nu _i ^\text{FD})$ given $\expec[M_i^2 \mid L]$ and $\mathrm{Var}(\hat \nu _i ^\text{Diff})$, shown in Fig.~\ref{fig:variance_predicted}.
The predicted and measured values agree well, supporting Eq.~\ref{eq:ratio-general} as an approximation to the variance reduction achieved by \diff{} relative to \fd{}.

\begin{figure}
    \centering

    \caption{Comparing the variance for \fd{} predicted by $R_i$ with the measured variance.}
    \label{fig:variance_predicted}
\end{figure}

